// Retrieve the extracted CV text from the previous node
const cvText = $input.first().json.text || $input.first().json.data?.text || '';

if (!cvText.trim()) {
  throw new Error('No text could be extracted from the PDF (scanned document?).');
}

const systemPrompt = `You are a technical recruiter analyzing a CV. Extract all technical skills and technologies mentioned, and rate proficiency 0-100 based on evidence in the CV (years of experience, projects, certifications, usage context).

Return ONLY a JSON array of objects with fields: skill_name (string), score (number 0-100), display_order (number starting from 1).

Scoring guide:
- 90+: expert / architect — deeply demonstrated
- 70-89: strong / advanced — regular use with clear depth
- 50-69: intermediate — listed with projects or experience
- 30-49: beginner — mentioned, some exposure
- below 30: listed but no depth shown

Include ALL technologies found. Prioritize programming languages, frameworks, tools, databases, cloud platforms, and methodologies.`;

return [{
  json: {
    model: 'deepseek-chat',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: `CV TEXT:\n${cvText.slice(0, 15000)}` }
    ],
    temperature: 0.3,
    max_tokens: 2000
  }
}];

// Get webhook data (talent_profile_id)
const webhookItem = $('Webhook').first();
const talentProfileId = webhookItem.json.talent_profile_id;

// Parse DeepSeek response
const aiResponse = $input.first().json;
const content = aiResponse.choices?.[0]?.message?.content;

if (!content) {
  throw new Error('AI returned empty response');
}

const jsonMatch = content.match(/\[[\s\S]*?\]/);
if (!jsonMatch) {
  throw new Error('AI response was not valid JSON');
}

const skills = JSON.parse(jsonMatch[0]);

if (!skills.length) {
  throw new Error('No skills detected in CV');
}

// Clamp scores 0-100
skills.forEach(function(s, i) {
  s.score = Math.max(0, Math.min(100, Math.round(s.score)));
  s.display_order = i + 1;
});

const techStack = skills.map(function(s) { return s.skill_name; });

// --- Write to Supabase via REST API ---
const supabaseUrl = $env.SUPABASE_URL || $env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = $env.SUPABASE_SERVICE_KEY || $env.SUPABASE_SERVICE_ROLE_KEY;

if (!supabaseUrl || !supabaseKey) {
  throw new Error('SUPABASE_URL and SUPABASE_SERVICE_KEY must be set as n8n environment variables');
}

const headers = {
  'apikey': supabaseKey,
  'Authorization': 'Bearer ' + supabaseKey,
  'Content-Type': 'application/json'
};

// 1. Delete existing skills
const deleteResp = await fetch(
  supabaseUrl + '/rest/v1/talent_skills?talent_profile_id=eq.' + encodeURIComponent(talentProfileId),
  { method: 'DELETE', headers }
);

if (!deleteResp.ok && deleteResp.status !== 204) {
  const err = await deleteResp.text();
  if (deleteResp.status !== 406) {
    throw new Error('Failed to delete existing skills: ' + err);
  }
}

// 2. Update tech_stack on talent_profiles
const updateResp = await fetch(
  supabaseUrl + '/rest/v1/talent_profiles?id=eq.' + encodeURIComponent(talentProfileId),
  {
    method: 'PATCH',
    headers,
    body: JSON.stringify({ tech_stack: techStack })
  }
);

if (!updateResp.ok) {
  const err = await updateResp.text();
  throw new Error('Failed to update tech_stack: ' + err);
}

// 3. Insert new skills
const skillRows = skills.map(function(s) {
  return {
    talent_profile_id: talentProfileId,
    skill_name: s.skill_name,
    score: s.score,
    display_order: s.display_order
  };
});

const insertResp = await fetch(
  supabaseUrl + '/rest/v1/talent_skills',
  {
    method: 'POST',
    headers: { ...headers, 'Prefer': 'return=minimal' },
    body: JSON.stringify(skillRows)
  }
);

if (!insertResp.ok) {
  const err = await insertResp.text();
  throw new Error('Failed to insert skills: ' + err);
}

return [{
  json: {
    success: true,
    talent_profile_id: talentProfileId,
    skill_count: skills.length,
    tech_stack: techStack
  }
}];
